%[text] 发现1：transfer 任务中的MO有互用ensemble单元
%[text:tableOfContents]{"heading":"目录"}
%[text] # 行为学，加速
%[text] ## A
%[text] 任务设计示意图，无代码
%[text] ## B
DataSetBas=TransferLearning.BasicTransferBehaviorDataSet;
SessionTableAL=DataSetBas.TableQuery(["Mouse","DateTime","Performance"],Group="声光水",Design="LightWater");
SessionTableAL.Group(:)="Transfer";
SessionTableLL=DataSetBas.TableQuery(["Mouse","DateTime","Performance"],Group="光声水",Design="LightWater");
SessionTableLL.Group(:)="Original";
[SummaryL,PValue]=UniExp.LearningSummarize([SessionTableAL;SessionTableLL]);
%%
figure;
Colors=GlobalOptimization.ColorAllocate(2,[1,1,1;1,1,1]);
Patches=MATLAB.Graphics.MultiShadowedLines(SummaryL.MeanCurve,SummaryL.SemCurve,EdgeColors=Colors(1:2,:));
legend(Patches,SummaryL.Properties.RowNames,Location='southeast');title('Light-water');
xlabel('Blocks');
ylabel('Hit rate');
title('Tested with Linear Mixed-Effect model');
text(2.5,0.8,sprintf('P=%.1g',PValue));
MATLAB.Graphics.FigureAspectRatio(1,1,MATLAB.Flags.Narrow);
print(TransferLearning.ProjectPath('Fig1B.svg'),'-dsvg');
%%
%[text] ## C
%[text] 光水和声水的学会95%会话数条形图
BehaviorDataSet=TransferLearning.BasicTransferBehaviorDataSet;
%%
SessionTableAL=BehaviorDataSet.TableQuery(["Mouse","DateTime","Performance"],Group="声光水",Design="LightWater");
SessionTableAL.Group(:)="Transfer";
SessionTableLL=BehaviorDataSet.TableQuery(["Mouse","DateTime","Performance"],Group="光声水",Design="LightWater");
SessionTableLL.Group(:)="Original";
SessionTableAA=BehaviorDataSet.TableQuery(["Mouse","DateTime","Performance"],Group="声光水",Design="AudioWater");
SessionTableAA.Group(:)="Original";
SessionTableLA=BehaviorDataSet.TableQuery(["Mouse","DateTime","Performance"],Group="光声水",Design="AudioWater");
SessionTableLA.Group(:)="Transfer";
SummaryL=UniExp.LearningSummarize([SessionTableAL;SessionTableLL],0.95);SummaryA=UniExp.LearningSummarize([SessionTableAA;SessionTableLA],0.95);
CompareGroup=table(["Original","Transfer"],'VariableNames',"GroupPair");
%%
Colors=table;
figure;
Layout2=tiledlayout(1,2,TileSpacing='tight',Padding='tight');
nexttile(Layout2);
Colors{"Scatter",["R","G","B"]}=[1,0,0];
CompareGroup.PLineOffset=6;
UniExp.BarScatterCompare(struct(Original=SummaryL.LearnedDays{"Original"}.Day,Transfer=SummaryL.LearnedDays{"Transfer"}.Day),CompareGroup,Colors);
ylim([0,16]);
box off
title('Light-water');
nexttile(Layout2);
Colors{"Scatter",["R","G","B"]}=[0.5,0,0];
CompareGroup.PLineOffset=2;
UniExp.BarScatterCompare(struct(Original=SummaryA.LearnedDays{"Original"}.Day,Transfer=SummaryA.LearnedDays{"Transfer"}.Day),CompareGroup,Colors);
box off
title('Audio-water');
ylabel(Layout2,'Blocks to 95% hit');
MATLAB.Graphics.FigureAspectRatio(8,5,MATLAB.Flags.Narrow);
print(TransferLearning.ProjectPath('Fig1C.svg'),'-dsvg');
%%
%[text] # 神经元，学会后更强反应Ensemble 被保存互用
QueryTablePath=TransferLearning.ProjectPath('查询表.xlsx');
%%
%[text] ## D
%[text] 脑区投射关系和注射位点示意图，无代码
%[text] ## E
%[text] 钙成像视野示例图，无代码
%[text] ## F
%[text] 声转光一个典型细胞的示例
QueryTable=UniExp.ReadQueryTable(QueryTablePath,'Fig1F');
CellNts=TransferLearning.FullCalcium.QueryNTS(QueryTable,UniExp.Flags.dFdF0,1:24);
CellUID=structfun(@(S)S.CellUID,CellNts,UniformOutput=false);
CellUID=MATLAB.Ops.IntersectN(1,CellUID.Naive_cue,CellUID.Naive,CellUID.Learned,CellUID.Transfer);
GroupNames=["Naive_cue","Naive","Learned","Transfer"];
for G=1:4
	NTS=CellNts.(GroupNames(G));
	[~,Index]=ismember(CellUID,NTS.CellUID);
	NTS=NTS(Index,:);
	[NTS.PeakValue,NTS.PeakTime]=max(NTS.TrialSignal(:,25:32),[],2);
	CellNts.(GroupNames(G))=NTS;
end
Logical=CellNts.Learned.PeakTime==CellNts.Transfer.PeakTime;
[Delta,Index]=max(min(CellNts.Learned.PeakValue(Logical),CellNts.Transfer.PeakValue(Logical)));
Index=find(Logical,Index);
Index=Index(end);
CellUID=CellUID(Index);
%%
PlotData=zeros(40,4);
for G=1:4
	PlotData(:,G)=CellNts.(GroupNames(G)).TrialSignal(Index,:);
end
PlotData(:,2)=PlotData(:,2)+max(PlotData(:,3))-min(PlotData(:,2));
PlotData(:,1)=PlotData(:,1)+max(PlotData(:,2))-min(PlotData(:,1));
%%
Fig=figure;
Axes=gobjects(1,2);
Xs=linspace(-3,2,40);
colororder([0,0,1;1,0,0;0,0.681,0]);
Layout=tiledlayout(1,2,TileSpacing='tight',Padding='tight');
Axes(1)=nexttile;
line(Xs,PlotData(:,1:3),LineWidth=1);
Axes(2)=nexttile;
line(Xs,PlotData(:,4),Color=[0,0,0],LineWidth=1);
MATLAB.Graphics.UnifyAxesLims(Axes,@ylim);
MATLAB.Graphics.FigureAspectRatio(1,1,MATLAB.Flags.Narrow);
for A=Axes
	A.YAxis.Visible='off';
	patch(A,[0,0.2,0.2,0],repelem(ylim,1,2),[0,0,0],FaceAlpha=0.3,LineStyle='none');
end
print(Fig,TransferLearning.ProjectPath('Fig1F.svg'),'-dsvg');
%%
%[text] ## 初始、学会和迁移模板
MOpBaseline=TransferLearning.MOpBaseline;
Titles=["🔊💧first","🔊💧last","💡💧Transfer"];
%%
%[text] ### G
%[text] 声水初始、学会和迁移到光水的热图
FigGI=UniExp.NtatsCellStrip(MOpBaseline.QueryNTATS(UniExp.ReadQueryTable(QueryTablePath,'Fig1GI'),UniExp.Flags.ZScore,1:24,UniExp.Flags.Median)); %[output:38dfdf9d]
%%
Fig=figure; %[output:07689322]
[Layout,Axes]=UniExp.LanearHeatmap(UniExp.HeatmapSort(FigGI,["Naive","Learned"]).NTATS{:,:,["Naive","Learned","Transfer"]},XData=[-3,3],LMHColor=[0,0,1;1,1,1;1,0,0],Flags=[UniExp.Flags.HideYAxis,UniExp.Flags.SymmetricColormap,UniExp.Flags.ScaleColor],Layout=tiledlayout(5,4,TileSpacing='none',Padding='tight')); %[output:07689322]
CB=colorbar; %[output:07689322]
CB.Layout.Tile=20; %[output:07689322]
CB.Label.String='z-score'; %[output:07689322]
CB.FontSize=20; %[output:07689322]
for A=1:3
	Axes(A).FontSize=15; %[output:07689322]
	xline(Axes(A),0,':k');
	xline(Axes(A),1,'-k');
	Axes(A).TickDir='in';
	Axes(A).Layout.TileSpan=[5,1];
	box(Axes(A),'on');
	title(Axes(A),Titles(A));
end
ylabel(Layout,sprintf('%u cells',height(FigGI)),FontSize=20); %[output:07689322]
MATLAB.Graphics.FigureAspectRatio(1,2,MATLAB.Flags.Amplify); %[output:07689322]
print(Fig,TransferLearning.ProjectPath('Fig1G.svg'),'-dsvg'); %[output:07689322]
%%
%[text] ### H
FigH=UniExp.NtatsCellStrip(MOpBaseline.QueryNTATS(UniExp.ReadQueryTable(QueryTablePath,'Fig1H'),UniExp.Flags.ZScore,1:24,UniExp.Flags.Median)); %[output:668344eb]
%%
PeakValue=max(FigH.NTATS,[],2);
Logical=PeakValue.Learned==max(PeakValue.Data,[],3);
[LnMean,LnSem]=MATLAB.DataFun.MeanSem(FigH.NTATS{Logical,:,["Naive_hit","Naive_miss","Learned"]},1);
LnMean=permute(LnMean,[2,3,1]);
LnSem=permute(LnSem,[2,3,1]);
[SpMean,SpSem]=MATLAB.DataFun.MeanSem(FigH.NTATS{~Logical,:,["Naive_hit","Naive_miss","Learned"]},1);
SpMean=permute(SpMean,[2,3,1]);
SpSem=permute(SpSem,[2,3,1]);
%%
Fig=figure; %[output:5f7456d3]
Layout=tiledlayout(3,2,TileSpacing='none',Padding='tight'); %[output:5f7456d3]
Xs=linspace(-3,3,height(LnMean)).';
Axes=gobjects(3,2);
for T=1:3
	Axes(T,1)=nexttile; %[output:5f7456d3]
	MATLAB.Graphics.MultiShadowedLines(LnMean(:,T),LnSem(:,T),1/2,X=Xs,EdgeColors=[0,0,0]);
	Axes(T,2)=nexttile;
	MATLAB.Graphics.MultiShadowedLines(SpMean(:,T),SpSem(:,T),1/2,X=Xs,EdgeColors=[0,0,0]);
end
for A=Axes(1:6)
	xline(A,0,':'); %[output:5f7456d3]
	xline(A,1,'-');
	A.YAxis.Visible='off';
end
Axes(1,1).XAxis.Visible='off'; %[output:5f7456d3]
Axes(2,1).XAxis.Visible='off'; %[output:5f7456d3]
Axes(1,2).XAxis.Visible='off'; %[output:5f7456d3]
Axes(2,2).XAxis.Visible='off'; %[output:5f7456d3]
title(Axes(1,1),sprintf('Learning\nensemble')); %[output:5f7456d3]
title(Axes(1,2),sprintf('Spontaneous\nensemble')); %[output:5f7456d3]
MATLAB.Graphics.UnifyAxesLims(Axes); %[output:5f7456d3]
MATLAB.Graphics.FigureAspectRatio(4,9,5/9); %[output:5f7456d3]
print(Fig,TransferLearning.ProjectPath('Fig1H.svg'),'-dsvg'); %[output:5f7456d3]
%%
%[text] ### I
Response=max(FigGI.NTATS(:,25:end,:),[],2);
Baseline=std(FigGI.NTATS(:,1:24,:),[],2).*3;
LearnedLogical=Response.Learned>Response.Naive&Response.Learned>Baseline.Learned;
TransferLogical=Response.Transfer>Response.Naive&Response.Transfer>Baseline.Transfer;
Learned=FigGI.NTATS{LearnedLogical,:,["Naive","Learned","Transfer"]};
[Mean,Sem]=MATLAB.DataFun.MeanSem(Learned,1);
Fig=figure; %[output:8ccf4c0a]
Lines=MATLAB.Graphics.MultiShadowedLines(permute(Mean,[2,3,1]),permute(Sem,[2,3,1]),1/4,EdgeColors=[1,0,0;0,0,1;0,0.681,0],X=linspace(-3,3,width(Mean)).'); %[output:8ccf4c0a]
xline(0,':'); %[output:8ccf4c0a]
xline(1,'-'); %[output:8ccf4c0a]
ylabel('z-score ± SEM'); %[output:8ccf4c0a]
legend(Lines,Titles,Location=MATLAB.Graphics.OptimizedLegendLocation(Lines)); %[output:8ccf4c0a]
title(sprintf('Learned %u cells, %s%% transfer',height(Learned),MATLAB.SignificantFixedpoint(sum(TransferLogical&LearnedLogical)/height(Learned)*100,2))); %[output:8ccf4c0a]
MATLAB.Graphics.FigureAspectRatio(4,3,2/3); %[output:8ccf4c0a]
print(Fig,TransferLearning.ProjectPath('Fig1I.svg'),'-dsvg'); %[output:8ccf4c0a]
%%
%[text] ### J
FigJ=UniExp.NtatsCellStrip(MOpBaseline.QueryNTATS(UniExp.ReadQueryTable(QueryTablePath,'Fig1J'),UniExp.Flags.ZScore,1:24,UniExp.Flags.Median)).NTATS; %[output:28a9e9e1]
Sample=FigJ(:,:,["naive_AudioWater","learned_AudioWater","transfer_LightWater"]);
Baseline=std(Sample(:,1:24,:),[],2).*3;
Response=max(Sample(:,25:end,:),[],2);
LearnedResponse=Response.learned_AudioWater;
TransferResponse=Response.transfer_LightWater;
Logical=TransferResponse>Baseline.transfer_LightWater&TransferResponse>Response.naive_AudioWater&LearnedResponse>TransferResponse&LearnedResponse>Baseline.learned_AudioWater;
%%
Sample=FigJ(Logical,:,:);
[~,SortIndex]=sort(LearnedResponse(Logical),'descend');
TitlesJ=["🔊","💡","🔊💧#1","🔊💧#9","💡💧#1"];
%%
Fig=figure; %[output:31e065d9]
Layout=tiledlayout(1,5,TileSpacing='none',Padding='tight'); %[output:31e065d9]
[~,Axes]=UniExp.LanearHeatmap(Sample{SortIndex,:,["naive_AudioOnly","naive_LightOnly","naive_AudioWater","learned_AudioWater","transfer_LightWater"]},XData=[-3,3],Layout=Layout,Flags=[UniExp.Flags.HideYAxis,UniExp.Flags.SymmetricColormap,UniExp.Flags.ScaleColor],LMHColor=[0,0,1;1,1,1;1,0,0]); %[output:31e065d9]
for A=1:5
	xline(Axes(A),0,':k'); %[output:31e065d9]
	xline(Axes(A),1,'-k');
	title(Axes(A),TitlesJ(A));
end
CB=colorbar; %[output:31e065d9]
CB.Label.String='z-score'; %[output:31e065d9]
MATLAB.Graphics.FigureAspectRatio(4,1,2/5); %[output:31e065d9]
print(Fig,TransferLearning.ProjectPath('Fig1J.svg'),'-dsvg'); %[output:31e065d9]
%%
%[text] ### K
FigK=structfun(@(T)height(unique(T)),MOpBaseline.TableQuery("TrialUID",UniExp.ReadQueryTable(TransferLearning.ProjectPath('查询表.xlsx'),'Fig1K')),UniformOutput=false);
figure; %[output:6d7fa06b]
Layout=tiledlayout(1,2,TileSpacing='none',Padding='tight'); %[output:6d7fa06b]
MATLAB.Graphics.NestedPie({[FigK.Learned_hit,FigK.Learned_miss]},AxesHandle=nexttile); %[output:8cae9415] %[output:6d7fa06b]
MATLAB.Graphics.NestedPie({[FigK.Transfer_hit,FigK.Transfer_miss]},AxesHandle=nexttile); %[output:5be627e3] %[output:6d7fa06b]
MATLAB.Graphics.FigureAspectRatio(2,1,1/3); %[output:6d7fa06b]
print(TransferLearning.ProjectPath('Fig1K.svg'),'-dsvg'); %[output:6d7fa06b]
%%
%[text] ### L
%[text] 模板细胞的命中错失
FigL=UniExp.NtatsCellStrip(MOpBaseline.QueryNTATS(UniExp.ReadQueryTable(QueryTablePath,'Fig1L'),UniExp.Flags.ZScore,1:24,UniExp.Flags.Median)); %[output:6e3e38a4]
Sample=FigL.NTATS(:,:,["Learned","Transfer_hit","Transfer_miss"]);
Baseline=std(Sample(:,1:24,:),[],2).*3;
Response=max(Sample(:,25:end,:),[],2);
LearnedResponse=Response.Learned;
TransferResponse=Response.Transfer_hit;
Logical=TransferResponse>Baseline.Transfer_hit&LearnedResponse>TransferResponse&LearnedResponse>Baseline.Learned;
[Mean,Sem]=MATLAB.DataFun.MeanSem(FigL.NTATS{Logical,:,["Transfer_hit","Transfer_miss"]},1);
Mean=permute(Mean,[2,3,1]);
Sem=permute(Sem,[2,3,1]);
Xs=linspace(-3,3,height(Mean)).';
Fig=figure; %[output:408535e5]
Layout=tiledlayout(2,1,TileSpacing='none',Padding='none'); %[output:408535e5]
Axes=gobjects(2,1);
for T=1:2
	Axes(T)=nexttile; %[output:408535e5]
	MATLAB.Graphics.MultiShadowedLines(Mean(:,T),Sem(:,T),1/2,X=Xs,EdgeColor='k');
	xline(0,':');
	xline(1,'-');
end
Axes(1).XAxis.Visible='off'; %[output:408535e5]
MATLAB.Graphics.FigureAspectRatio(1,1,1/4); %[output:408535e5]
MATLAB.Graphics.UnifyAxesLims(Axes,@ylim); %[output:408535e5]
print(Fig,TransferLearning.ProjectPath('Fig1L.svg'),'-dsvg'); %[output:408535e5]

